    # Replace values using dictionary mapping
    df = df.replace(dct)

    missing_columns = df.isna().any().to_numpy()
    if missing_columns.any():
        correlation_matrix = np.full((df.shape[1], df.shape[1]), np.nan)
        unaffected_columns = ~missing_columns
        if unaffected_columns.any():
            correlation_matrix[np.ix_(unaffected_columns, unaffected_columns)] = np.corrcoef(df.values[:, unaffected_columns], rowvar=False)
        return pd.DataFrame(correlation_matrix, columns=df.columns, index=df.columns)

    # Calculate the correlation matrix
    correlation_matrix = np.corrcoef(df.values, rowvar=False)

    return pd.DataFrame(correlation_matrix, columns=df.columns, index=df.columns)

