from sklearn.cluster import DBSCAN

def task_func(data, cols):
    df = pd.DataFrame(data, columns=cols)
    dbscan = DBSCAN(eps=3, min_samples=2)
    labels = dbscan.fit_predict(df)
    unique_clusters = set(int(l) for l in labels if l != -1)
    if len(unique_clusters) > 1:
        mapping = {}
        for l in labels:
            l = int(l)
            if l != -1 and l not in mapping:
                mapping[l] = len(mapping)
        labels = [mapping[int(l)] if int(l) != -1 else -1 for l in labels]
    df['Cluster'] = labels
    return df

import pandas as pd
from sklearn.cluster import DBSCAN

def task_func(data, cols):
    df = pd.DataFrame(data, columns=cols)
    feature_vectors = df.to_numpy()
    dbscan = DBSCAN(eps=3, min_samples=2)
    df['Cluster'] = dbscan.fit_predict(df)
    clusters = set(df['Cluster']) - {-1}
    if len(clusters) > 1:
        ordered_clusters = sorted(clusters, key=lambda cluster: min(tuple(vector) for vector in feature_vectors[df['Cluster'] == cluster]))
        cluster_mapping = {cluster: index for index, cluster in enumerate(ordered_clusters)}
        df['Cluster'] = df['Cluster'].replace(cluster_mapping)
    return df

